package org.taku.tryon.realtime;import android.os.Bundle;import android.content.Context;public class TryOnController{public static final String OUTFIT="outfit";public static int starts;public static boolean visible,accept=true;public static Bundle lastArgs;static void visible(boolean value){visible=value;}public static Bundle start(Context context,Bundle args){if(!visible)throw new AssertionError("start before parent foreground");starts++;lastArgs=new Bundle(args);Bundle result=new Bundle();result.putBoolean("ok",accept);result.putString("code",accept?"starting":"busy");if(accept)result.putLong("attemptGeneration",CallTryOnService.generation);return result;}}
